{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 대한 근거를 바탕으로 적절한 개선책을 선택했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에 3.2초가 걸려 개선이 필요했던 상황을 설명한다.",
          "task": "신고 목록 조회 쿼리의 병목에 맞는 개선책을 선택해야 했던 과제를 설명한다.",
          "action": "실행 계획과 조회 조건에서 확인한 병목을 근거로 인덱스 추가와 조인 정리를 선택한 이유를 설명한다.",
          "result": "선택한 개선책의 효과를 뒷받침하는 전후 조회 시간 등 실제 확인한 결과를 제시한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 판단 근거가 확인한 쿼리 병목과 연결되어 있다.",
          "실행 계획이나 조회 조건에서 확인한 내용이 개선책의 선택 이유를 뒷받침한다.",
          "조회 시간이 3.2초에서 0.4초로 줄어든 결과 등 선택한 개선책의 효과를 뒷받침하는 수치가 제시된다."
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 개선했을 때, 인덱스 추가와 조인 정리를 개선책으로 선택한 판단 근거는 무엇이었나요?",
      "answerTip": "본인이 직접 경험한 내용을 중심으로 차분하게 답변해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회 쿼리의 실행 계획이나 조회 조건에서 확인한 구체적인 병목을 제시하고, 인덱스 추가와 조인 정리가 그 병목에 적합했던 이유를 연결한다.",
            "신고 목록 조회 쿼리의 개선 전후 시간을 수치로 제시해 선택한 개선책의 효과를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회 쿼리에 인덱스 추가와 조인 정리를 선택한 이유를 제시하지만, 실행 계획이나 조회 조건의 실제 관찰 내용과 연결하지 못하고 일반적인 성능 개선 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회 쿼리에 적용한 작업이나 단축된 시간만 나열하고, 해당 개선책을 선택한 판단 근거를 제시하지 못하거나 다른 API 개발 이야기를 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류에서 로그의 관찰 내용을 근거로 원인을 특정한 판단을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송되는 오류가 발생했던 상황을 설명한다.",
          "task": "알림 중복 발송을 일으킨 원인을 로그에서 좁혀야 했던 과제를 설명한다.",
          "action": "시간순 로그에서 확인한 실행 시점과 서버별 실행 흔적 등 실제 관찰 내용을 제시하고, 이를 스케줄러 중복 실행의 근거로 해석한 이유를 설명한다.",
          "result": "관찰한 로그가 두 서버의 스케줄러 동시 실행과 알림 중복 발송을 어떻게 연결해 원인 판단을 뒷받침했는지 설명한다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행을 원인으로 좁히는 데 결정적이었던 실제 로그 관찰 내용이 제시된다.",
          "두 서버에서의 스케줄러 실행 흔적이 알림 중복 발송 증상과 연결되는 이유가 설명된다."
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적했을 때, 스케줄러 중복 실행을 원인으로 좁힌 결정적인 로그 근거는 무엇이었나요?",
      "answerTip": "기억나는 실제 장면을 중심으로 답변을 정리해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 당시 로그에서 확인한 실행 시점이나 서버별 실행 흔적을 구체적으로 제시하고, 두 서버의 스케줄러 실행이 중복 발송의 원인이라고 판단한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송 당시 두 서버의 스케줄러 실행 로그를 근거로 제시하지만, 실제 확인한 로그 내용이 모호하거나 해당 흔적이 중복 발송을 설명하는 이유가 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송의 원인이 스케줄러였다는 결론만 말하고 로그 근거를 제시하지 못하거나, 잠금 적용 등 수정 작업만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고, 확인되지 않은 용량을 근거로 투약을 중단하는 판단 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황을 설명한다.",
          "task": "해당 처방에 따라 투약해도 되는지 판단해야 했던 시점을 설명한다.",
          "action": "처방 용량을 무엇과 비교했으며, 어떤 불일치가 해소되지 않아 투약을 멈춰야 한다고 판단했는지 설명한다.",
          "result": "담당의 확인으로 입력 오류임이 밝혀졌다는 결과를 중단 판단의 근거와 연결한다."
        },
        "expectedEvidence": [
          "용량의 차이를 단순히 평소와 다르다는 인상으로 넘기지 않고, 적정성이 확인되지 않으면 투약을 중단한다는 판단 기준",
          "진통제 처방 용량을 비교한 기준과 실제로 발견한 차이",
          "담당의 확인에서 밝혀진 입력 오류와 중단 판단의 연결"
        ]
      },
      "question": "진통제 처방 용량이 평소의 두 배였던 경험에서, 수술 후 환자의 투약을 진행하지 않고 멈춰야 한다고 판단한 기준은 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 소개하고 본인의 판단을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방 용량을 비교한 기준과 두 배의 차이를 구체적으로 설명하고, 용량의 적정성이 확인되지 않아 투약을 멈춰야 했다는 이유를 입력 오류 확인 결과와 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방 용량이 평소와 달라 투약을 멈췄다는 기준은 제시하지만, 비교 근거나 확인 전 투약하면 안 된다고 판단한 이유는 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 중단한 판단 기준을 제시하지 않거나, 처방 용량의 의심 여부와 무관한 투약 경험만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화 중 간호기록에 남길 내용을 어떤 기준으로 정했는지 확인하여, 변화가 드러나는 정확한 기록을 작성하는 역량을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 활력징후나 통증을 관찰하면서 이전 상태와 다른 변화를 확인한 사례를 설명한다.",
          "task": "관찰된 상태 변화가 간호기록에 정확히 드러나도록 기록할 내용을 정해야 했음을 설명한다.",
          "action": "관찰 시점과 이전 상태 대비 차이 등 실제 사례에서 적용한 기록 내용 선정 기준을 설명한다.",
          "result": "그 기준에 따라 남긴 간호기록에서 환자 상태의 변화를 어떻게 확인할 수 있었는지 설명한다."
        },
        "expectedEvidence": [
          "환자 상태 변화가 드러나도록 간호기록에 남길 내용을 정한 구체적인 기준",
          "해당 기준을 적용한 실제 활력징후 또는 통증 변화와 기록 내용",
          "기록한 내용으로 관찰 시점이나 이전 상태와의 차이를 확인할 수 있다는 설명"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자를 관찰했던 경험 중, 상태 변화가 있었던 한 사례에서 간호기록에 남길 내용을 정한 기준은 무엇이었나요?",
      "answerTip": "여러 경험을 나열하기보다 한 사례에 집중해 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "간호기록에 남길 내용을 정한 기준을 관찰 시점이나 이전 상태 대비 차이처럼 구체적으로 제시하고, 실제 활력징후 또는 통증 기록을 들어 그 기준이 환자 상태 변화를 드러내는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태가 달라진 내용을 간호기록에 남긴다는 기준은 제시하지만, 실제 활력징후 또는 통증 기록에 어떻게 적용했는지나 해당 내용을 고른 이유는 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "간호기록에 남길 내용을 정한 기준을 제시하지 않거나, 환자 상태 변화의 기록과 관계없는 업무만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P20",
  "interviews": [
    {
      "categoryId": "P20-C1",
      "itemId": "P20-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "고객의 상황과 요청을 확인한 내용을 바탕으로 배송 정보를 고객이 이해하기 쉬운 채팅 안내 문구로 전달할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "채널톡으로 배송 관련 문의를 받았으며 고객의 설명만으로는 상황이나 요청이 명확하지 않았던 사례이다.",
          "task": "확인된 고객 상황과 요청에 맞춰 정확하고 이해하기 쉬운 배송 안내 문구를 작성해야 했다.",
          "action": "실제로 전달한 안내 문구를 제시하고, 확인된 배송 정보와 고객의 요청을 해당 표현에 어떻게 반영했는지 설명한다.",
          "result": "해당 안내에 대한 고객의 반응이나 추가 질문 여부 등 문구의 이해도를 확인할 수 있었던 내용을 설명한다."
        },
        "expectedEvidence": [
          "확인된 배송 정보를 고객이 이해할 수 있는 말로 풀어 쓴 실제 안내 문구",
          "안내 문구에 반영된 고객의 핵심 상황과 요청",
          "해당 표현을 선택한 이유 또는 안내 후 고객의 이해를 확인할 수 있는 반응"
        ]
      },
      "question": "마루커머스에서 채널톡으로 배송 문의에 응대했을 때, 확인한 고객의 상황과 요청에 맞춰 배송 정보를 쉽게 풀어 전달했던 안내 문구는 무엇이었나요?",
      "answerTip": "기억나는 한 사례를 골라 당시 표현을 떠올리며 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "배송 문의에 실제로 사용한 안내 문구를 제시하며, 확인된 고객 상황과 요청에 맞춰 배송 정보를 정확하고 쉬운 표현으로 전달한 내용이 드러난다.",
            "배송 안내 문구의 표현을 선택한 이유를 고객의 상황이나 이해를 확인한 반응과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "배송 정보를 전달했던 안내 문구는 제시하지만, 일반적인 배송 안내에 머물거나 고객의 상황과 요청에 맞춰 표현한 이유가 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "배송 안내 문구를 제시하지 않고 주문번호를 확인했다는 설명만 하거나, 고객의 요청과 다른 배송 정보를 안내한 내용에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P20-C1",
      "itemId": "P20-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환불을 직접 승인할 수 없는 상황에서 정책과 처리 권한의 범위를 지키면서 고객에게 실행 가능한 대안을 제시할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "마루커머스에서 배송 지연에 화가 난 고객이 환불을 요구했으나 인턴에게는 환불 승인 권한이 없었다.",
          "task": "환불을 임의로 약속하지 않으면서 고객에게 정책과 권한 범위 내에서 가능한 대안을 제시해야 했다.",
          "action": "당시 고객에게 제시한 대안의 구체적인 내용을 밝히고, 환불 정책과 본인의 처리 권한상 그 대안을 제시한 이유를 설명한다.",
          "result": "제시한 대안에 고객이 보인 반응 등 실제로 확인된 결과를 설명한다."
        },
        "expectedEvidence": [
          "환불 요구에 대해 고객에게 실제로 제시한 실행 가능한 대안의 내용",
          "해당 대안이 환불 정책과 본인의 승인 권한 범위를 벗어나지 않는다고 판단한 근거",
          "대안을 전달한 뒤 확인한 고객의 반응"
